use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is declared over. A subscription
/// outside this set is recorded as a failure rather than requested, because a
/// request outside the allowlist would trap and take every other feed with it.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an `http`/`https` URL, lowercased, or `None` if the URL
/// is not something this node should ask for.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return None;
    };

    // Authority ends at the first path, query, or fragment delimiter.
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Strip any userinfo: the real host follows the last '@'.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // No IPv6 literals: none of the allowed hosts is one.
    if host_port.starts_with('[') {
        return None;
    }

    let host = match host_port.find(':') {
        Some(i) => {
            let port = &host_port[i + 1..];
            if !port.chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            &host_port[..i]
        }
        None => host_port,
    };

    if host.is_empty() {
        return None;
    }
    if !host
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-')
    {
        return None;
    }
    Some(host.to_string())
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let url = url.trim().to_string();
            if url.is_empty() {
                continue;
            }
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in this node's HTTP allowlist".to_string(),
                });
                continue;
            }
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
